arguments.sql:
SELECT 
    c.CustomerID,
    c.CompanyName
FROM Customers c
WHERE c.CustomerID IN (
    SELECT CustomerID FROM Orders WHERE OrderDate >= '2023-08-01' AND OrderDate < '2023-09-01'
)
AND c.CustomerID NOT IN (
    SELECT CustomerID FROM Orders WHERE OrderDate >= '2023-09-01' AND OrderDate < '2023-10-01'
);
